item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['bioconductor-deseq2','gseapy']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print(repo)
        for t in data.get('tags', [])[:10]:
            print(' ', t.get('name'))
    except Exception as e:
        print(repo, 'ERR', repr(e))
PY"

